/* qc-20: flame test with ion selection plus a spectroscope-style observation strip. */
S.flame=function(root,done){var ions=[['Na⁺ · সোডিয়াম','#ffd21f','উজ্জ্বল হলুদ'],['K⁺ · পটাশিয়াম','#b48cff','হালকা বেগুনি'],['Ca²⁺ · ক্যালসিয়াম','#ff7043','ইট-লাল'],['Cu²⁺ · কপার','#35e0b0','নীলাভ-সবুজ'],['Ba²⁺ · বেরিয়াম','#a3e635','আপেল-সবুজ'],['Li⁺ · লিথিয়াম','#fb4964','গাঢ় লাল']];var cv=canvas(root,680,320),x=cv.x,sel=0;buttons(root,ions.map(function(it,i){return{label:it[0],primary:i===0,click:function(){sel=i;done&&done();}}}));frame(root,function(dt,t){var it=ions[sel];bg(x,cv.w,cv.h);text(x,'শিখা পরীক্ষা · ধাতব আয়ন শনাক্তকরণ',18,24,18,'#e2e8f0',true);var cx=180,base=245;x.fillStyle='#475569';x.fillRect(cx-35,base,70,20);x.fillStyle='#64748b';x.fillRect(cx-24,base-35,48,35);x.beginPath();x.moveTo(cx,base-35);x.bezierCurveTo(cx-55,base-95,cx-35,base-150,cx,base-192+Math.sin(t*5)*5);x.bezierCurveTo(cx+40,base-130,cx+58,base-78,cx,base-35);x.closePath();var grad=x.createLinearGradient(cx,base-190,cx,base-35);grad.addColorStop(0,'#fff7ed');grad.addColorStop(.28,it[1]);grad.addColorStop(1,'rgba(251,146,60,.05)');x.fillStyle=grad;x.fill();text(x,it[0],300,80,21,it[1],true);text(x,'পর্যবেক্ষিত বৈশিষ্ট্য: '+it[2],300,112,15,'#e2e8f0',true);text(x,'স্পেকট্রোস্কোপে দেখা গেলে রেখাগুলোর বিন্যাস আরও নির্দিষ্ট',300,147,12,'#94a3b8');var colors=[it[1],'#2b4052',it[1],'#2b4052','#2b4052',it[1],'#2b4052',it[1],'#2b4052'];for(var i=0;i<colors.length;i++){x.fillStyle=colors[i];x.fillRect(300+i*35,190,12,45);}text(x,'রঙের বারটি কেবল পর্যবেক্ষণকে সাজিয়ে দেখায়—এটি পরিমাপ করা line spectrum নয়।',300,258,11,'#94a3b8');text(x,'শিখার রঙ দেখে শনাক্তকরণ প্রাথমিক পরীক্ষা; মিশ্র আয়নে রঙ মিশে যেতে পারে।',18,298,12,'#cbd5e1');});};

/* Make the p-orbital nodal plane match the selected orbital's orientation. */
var originalOrbitals=S.orbitals;
S.orbitals=function(root,done){var cv=canvas(root,680,320),x=cv.x,shape='s';buttons(root,[{label:'s',primary:true,click:function(){shape='s';done&&done();}},{label:'pₓ',click:function(){shape='px';done&&done();}},{label:'pᵧ',click:function(){shape='py';done&&done();}},{label:'dₓᵧ',click:function(){shape='dxy';done&&done();}},{label:'dᶻ²',click:function(){shape='dz2';done&&done();}}]);frame(root,function(){bg(x,cv.w,cv.h);text(x,'অরবিটালের আকৃতি ও নোডাল অঞ্চল',18,24,17,'#e2e8f0',true);var cx=300,cy=160;x.fillStyle='rgba(56,189,248,.3)';x.strokeStyle='#38bdf8';x.lineWidth=2;if(shape==='s'){x.beginPath();x.arc(cx,cy,70,0,TAU);x.fill();x.stroke();text(x,'s: গোলীয়',420,130,15);}else if(shape==='px'||shape==='py'){if(shape==='px'){x.beginPath();x.ellipse(cx-43,cy,48,32,0,0,TAU);x.ellipse(cx+43,cy,48,32,0,0,TAU);x.fill();x.stroke();line(x,cx,cy-85,cx,cy+85,'#fbbf24',2,[4,4]);}else{x.beginPath();x.ellipse(cx,cy-43,32,48,0,0,TAU);x.ellipse(cx,cy+43,32,48,0,0,TAU);x.fill();x.stroke();line(x,cx-85,cy,cx+85,cy,'#fbbf24',2,[4,4]);}text(x,shape==='px'?'pₓ: y-z নোডাল সমতল':'pᵧ: x-z নোডাল সমতল',420,130,13);}else if(shape==='dxy'){for(var i=0;i<4;i++){var a=Math.PI/4+i*Math.PI/2;x.beginPath();x.ellipse(cx+Math.cos(a)*46,cy+Math.sin(a)*46,42,23,a,0,TAU);x.fill();x.stroke();}text(x,'dₓᵧ: চারটি লোব',420,130,13);}else{x.beginPath();x.ellipse(cx,cy-57,22,48,0,0,TAU);x.ellipse(cx,cy+57,22,48,0,0,TAU);x.fill();x.stroke();x.beginPath();x.ellipse(cx,cy,62,24,0,0,TAU);x.stroke();text(x,'dᶻ²: দুই লোব + টোরাস',420,130,13);}dot(x,cx,cy,3,'#fbbf24');text(x,'এগুলো 2D স্কিম্যাটিক; বাস্তব অরবিটাল হলো 3D probability distribution।',18,296,12,'#94a3b8');});};

/* qc-31: show the core shells after losing/gaining electrons; don't leave electrons on a fictional empty shell. */
S.valenceShell=function(root,done){var cv=canvas(root,680,320),x=cv.x;var ctl=controls(root,[{label:'নিরপেক্ষ প্রধান-গ্রুপ পরমাণুর যোজ্যতা ইলেকট্রন',min:1,max:8,value:7}],done);frame(root,function(){var e=ctl.read()[0],loss=e<=3?e:0,gain=e>=5&&e<=7?8-e:0,after=e<=3?8:e>=5&&e<=7?8:e;bg(x,cv.w,cv.h);text(x,'যোজ্যতা ইলেকট্রন ও আয়ন গঠন',18,24,18,'#e2e8f0',true);function atom(cx,vals,highlight){var cy=150;dot(x,cx,cy,17,'#fb7185');text(x,'+',cx,cy+4,12,'#071421',true,'center');for(var sh=0;sh<vals.length;sh++){var r=31+sh*29;x.strokeStyle=sh===vals.length-1?'#fbbf24':'#456075';x.lineWidth=sh===vals.length-1?2.3:1.2;x.beginPath();x.arc(cx,cy,r,0,TAU);x.stroke();for(var j=0;j<vals[sh];j++){var a=TAU*j/Math.max(1,vals[sh])-Math.PI/2;dot(x,cx+r*Math.cos(a),cy+r*Math.sin(a),4.4,sh===vals.length-1?'#fbbf24':'#38bdf8');}}}var initial=e<=2?[2,e]:[2,8,e];if(e===8)initial=[2,8];if(e===1||e===2)initial=[e];atom(145,initial);text(x,'আগে',116,260,14,'#cbd5e1',true);var afterShells;if(e<=2)afterShells=[Math.max(0,e-loss)];else if(e<=3)afterShells=[2,Math.max(0,8-loss)];else if(e>=5&&e<=7)afterShells=[2,8,8];else if(e===4)afterShells=[2,8,4];else afterShells=[2,8];atom(495,afterShells);text(x,'পরে / প্রবণতা',440,260,14,'#cbd5e1',true);var msg=e<=3?'ধনায়ন: '+loss+'টি e⁻ ত্যাগ; ভেতরের পূর্ণ শেল প্রকাশ পায়':e>=5&&e<=7?'ঋণায়ন: '+gain+'টি e⁻ গ্রহণ; বহিঃস্তরে ৮টি e⁻ হয়':e===4?'প্রায়ই ইলেকট্রন ভাগাভাগি/সমযোজী বন্ধন':'পূর্ণ বহিঃস্তর; সাধারণত সহজে আয়ন হয় না';text(x,msg,205,70,14,'#34d399',true);text(x,'সরল প্রধান-গ্রুপ মডেল; H-এর duet rule ও বাস্তব যৌগের ব্যতিক্রম আছে।',18,300,11,'#94a3b8');});};

/* Existing p-cloud sampling used abs(cos) with sign(cos)*cos, collapsing both lobes rightward. */
S.electroncloud=function(root,done){var cv=canvas(root,680,320),x=cv.x;var ctl=controls(root,[{label:'অরবিটাল: 0 = s, 1 = pₓ',min:0,max:1,value:0},{label:'মেঘের বিস্তার',min:30,max:100,value:65}],done);frame(root,function(dt,t){var v=ctl.read(),p=v[0]===1,spread=v[1],cx=250,cy=155;bg(x,cv.w,cv.h);text(x,'আধুনিক পরমাণু মডেল: ইলেকট্রন probability cloud',18,24,17,'#e2e8f0',true);dot(x,cx,cy,10,'#fb7185');for(var i=0;i<1050;i++){var u=(i*.61803398875)%1,a=i*2.3999632297+t*.012,r=spread*(.08+Math.sqrt(u)),xx,yy;if(p){var cs=Math.cos(a),sn=Math.sin(a);r*=.12+.88*Math.abs(cs);xx=cx+r*cs;yy=cy+r*sn*.55;}else{xx=cx+r*Math.cos(a);yy=cy+r*Math.sin(a)*.78;}var alpha=Math.max(.07,.4*(1-r/(spread*1.2)));x.fillStyle='rgba(56,189,248,'+alpha+')';x.beginPath();x.arc(xx,yy,1.5,0,TAU);x.fill();}if(p){line(x,cx,cy-100,cx,cy+100,'#fbbf24',1.5,[4,4]);text(x,'নোডাল সমতল',cx+8,cy+115,11,'#fbbf24');}text(x,p?'pₓ অরবিটাল: দুটি বিপরীত লোব':'s অরবিটাল: গোলীয় সম্ভাব্যতার মেঘ',395,100,14,'#38bdf8',true);text(x,'ঘন বিন্দু = ঐ অঞ্চলে ইলেকট্রন পাওয়ার সম্ভাবনা বেশি।',395,133,12);text(x,'ইলেকট্রনের নির্দিষ্ট ক্লাসিক্যাল পথ নয়।',395,158,12);text(x,'স্কিম্যাটিক; বাস্তব wavefunction-এর পূর্ণ গণনা নয়।',18,295,12,'#94a3b8');});};

/* Full 31-concept audit fixes: conservation, valid orbital filling, shell capacity, and ion comparisons. */

/* qc-02: explicit particle conservation before/after a simple 1:1 A + B -> AB model. */
S.atomCounting=function(root,done){
 var cv=canvas(root,680,330),x=cv.x,mode=0;
 var ctl=controls(root,[{label:'A মৌলের পরমাণু',min:1,max:8,value:4},{label:'B মৌলের পরমাণু',min:1,max:8,value:2}],done);
 buttons(root,[{label:'মৌল দেখুন',primary:true,click:function(){mode=0;done&&done();}},{label:'AB যৌগ',click:function(){mode=1;done&&done();}},{label:'বিক্রিয়ার আগে → পরে',click:function(){mode=2;done&&done();}}]);
 frame(root,function(){var v=ctl.read(),a=v[0],b=v[1],pairs=Math.min(a,b),leftA=a-pairs,leftB=b-pairs;bg(x,cv.w,cv.h);text(x,'ডাল্টনের পরমাণুবাদ · পরমাণু পুনর্বিন্যস্ত হয়, নষ্ট হয় না',18,24,17,'#e2e8f0',true);
 function atom(px,py,c,t){dot(x,px,py,12,c);text(x,t,px,py+4,11,'#071421',true,'center');}
 function molecule(px,py){atom(px,py,'#38bdf8','A');atom(px+25,py,'#fbbf24','B');line(x,px+12,py,px+13,py,'#e2e8f0',2);}
 function gridAtoms(xs,ys,count,c,t){for(var i=0;i<count;i++)atom(xs+(i%4)*48,ys+Math.floor(i/4)*38,c,t);}
 if(mode===0){text(x,'A পরমাণু',25,61,13,'#38bdf8',true);gridAtoms(35,91,a,'#38bdf8','A');text(x,'B পরমাণু',365,61,13,'#fbbf24',true);gridAtoms(375,91,b,'#fbbf24','B');text(x,'A = '+a+'টি · B = '+b+'টি',25,220,16,'#e2e8f0',true);}
 else if(mode===1){text(x,'তৈরি AB অণু: '+pairs+'টি',25,61,14,'#38bdf8',true);for(var i=0;i<pairs;i++)molecule(45+(i%4)*82,95+Math.floor(i/4)*55);text(x,'অবশিষ্ট A: '+leftA+'টি · অবশিষ্ট B: '+leftB+'টি',25,220,15,'#fbbf24',true);for(var j=0;j<leftA;j++)atom(35+j*31,254,'#38bdf8','A');for(var k=0;k<leftB;k++)atom(35+(leftA+k)*31,292,'#fbbf24','B');}
 else{text(x,'আগে',25,58,14,'#cbd5e1',true);text(x,'A: '+a,25,78,12,'#38bdf8');gridAtoms(35,105,a,'#38bdf8','A');text(x,'B: '+b,25,195,12,'#fbbf24');gridAtoms(35,215,b,'#fbbf24','B');line(x,300,160,350,160,'#fbbf24',3);text(x,'পরে',375,58,14,'#cbd5e1',true);text(x,'AB অণু: '+pairs,375,78,12,'#38bdf8');for(var m=0;m<pairs;m++)molecule(390+(m%4)*70,105+Math.floor(m/4)*54);var idx=0;for(var u=0;u<leftA;u++){atom(390+(idx%4)*54,223+Math.floor(idx/4)*35,'#38bdf8','A');idx++;}for(var w=0;w<leftB;w++){atom(390+(idx%4)*54,223+Math.floor(idx/4)*35,'#fbbf24','B');idx++;}text(x,'সংরক্ষিত: A '+pairs+'+'+leftA+' = '+a+'; B '+pairs+'+'+leftB+' = '+b,18,311,12,'#34d399',true);}
 text(x,'এটি শিক্ষণ-উদাহরণ: 1:1 AB গঠন ধরা হয়েছে; বাস্তব যৌগের অনুপাত সূত্র অনুযায়ী নির্ধারিত হয়।',18,328,10,'#94a3b8');
 });
};

function auditedOrbitalOccupancy(e,cap){var n=cap/2,out=[];for(var i=0;i<n;i++)out.push(0);for(var j=0;j<Math.min(e,n);j++)out[j]=1;for(var k=0;k<n&&e>n;k++){out[k]=2;e--;}return out;}
/* qc-14: show valid degenerate-orbital occupancy (Hund before pairing), with Cr/Cu exceptions. */
S.aufbau=function(root,done){var cv=canvas(root,680,360),x=cv.x;var ctl=controls(root,[{label:'নিরপেক্ষ পরমাণুর ইলেকট্রন সংখ্যা Z',min:1,max:36,value:17}],done);var subs=[['1s',2],['2s',2],['2p',6],['3s',2],['3p',6],['4s',2],['3d',10],['4p',6]];
 frame(root,function(){var e=ctl.read()[0],rem=e,used=[];subs.forEach(function(s){var n=Math.min(rem,s[1]);rem-=n;used.push(n);});if(e===24){used[5]=1;used[6]=5;}if(e===29){used[5]=1;used[6]=10;}bg(x,cv.w,cv.h);text(x,'আউফবাউ নীতি · শক্তি-ক্রমে ইলেকট্রন বিন্যাস',18,24,17,'#e2e8f0',true);text(x,'প্রতিটি সমশক্তির p/d অরবিটালে আগে একক ইলেকট্রন; তারপর জোড়া।',18,45,12,'#94a3b8',true);
 subs.forEach(function(s,i){var val=used[i],count=s[1]/2,occ=auditedOrbitalOccupancy(val,s[1]),y=58+i*34;text(x,s[0],18,y+19,13,val?'#38bdf8':'#8296aa',true);for(var b=0;b<count;b++){var px=80+b*37,w=31;x.strokeStyle='#486176';x.strokeRect(px,y,w,26);if(occ[b]>=1)text(x,'↑',px+4,y+20,18,'#38bdf8',true);if(occ[b]>=2)text(x,'↓',px+17,y+20,18,'#fbbf24',true);}text(x,val+'/'+s[1],280,y+18,11,'#cbd5e1');});
 text(x,'Z = '+e+' · মোট ইলেকট্রন = '+e,405,80,15,'#fbbf24',true);text(x,e===24?'Cr: [Ar] 3d⁵ 4s¹ (ব্যতিক্রম)':e===29?'Cu: [Ar] 3d¹⁰ 4s¹ (ব্যতিক্রম)':'Cr/Cu ব্যতিক্রমের জন্য নির্দিষ্ট বিন্যাস আলাদাভাবে দেখানো হয়।',405,112,12,'#cbd5e1');text(x,'উপস্তরের শক্তি-ক্রম ধারণামূলক; এটি পূর্ণ many-electron quantum calculation নয়।',18,345,11,'#94a3b8');
 });};

/* qc-19: correct main-group group-number mapping while showing a concrete element. */
S.valence=function(root,done){var cv=canvas(root,680,320),x=cv.x;var ctl=controls(root,[{label:'পারমাণবিক সংখ্যা Z (প্রথম 20 মৌল)',min:1,max:20,value:17}],done);var names=['','H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca'];var full=['','1s¹','1s²','1s² 2s¹','1s² 2s²','1s² 2s² 2p¹','1s² 2s² 2p²','1s² 2s² 2p³','1s² 2s² 2p⁴','1s² 2s² 2p⁵','1s² 2s² 2p⁶','[Ne] 3s¹','[Ne] 3s²','[Ne] 3s² 3p¹','[Ne] 3s² 3p²','[Ne] 3s² 3p³','[Ne] 3s² 3p⁴','[Ne] 3s² 3p⁵','[Ne] 3s² 3p⁶','[Ar] 4s¹','[Ar] 4s²'];
 function shells(z){if(z<=2)return[z];if(z<=10)return[2,z-2];if(z<=18)return[2,8,z-10];return[2,8,8,z-18];}
 function group(z){if(z===1)return 1;if(z===2||z===10||z===18)return 18;if(z===3||z===11||z===19)return 1;if(z===4||z===12||z===20)return 2;if(z>=5&&z<=9)return z+8;if(z>=13&&z<=17)return z;return 1;}
 frame(root,function(){var z=ctl.read()[0],sh=shells(z),ve=sh[sh.length-1],g=group(z),tendency=ve===1||ve===2?'সাধারণত ইলেকট্রন ত্যাগের প্রবণতা':ve===3?'ধনায়ন/বন্ধন গঠনে অংশ নিতে পারে':ve===4?'বিভিন্ন ধরনের বন্ধনে অংশ নেয়':ve<=7?'অক্টেট পূরণে ইলেকট্রন গ্রহণ/ভাগ করতে পারে':'পূর্ণ বহিঃস্তর; তুলনামূলক নিষ্ক্রিয়';bg(x,cv.w,cv.h);text(x,'ইলেকট্রন বিন্যাস → যোজ্যতা → মৌলের ধর্ম',18,24,17,'#e2e8f0',true);var cx=165,cy=151;sh.forEach(function(num,si){var r=27+si*26;x.strokeStyle=si===sh.length-1?'#fbbf24':'#466177';x.lineWidth=si===sh.length-1?2.5:1.2;x.beginPath();x.arc(cx,cy,r,0,TAU);x.stroke();for(var j=0;j<num;j++){var a=TAU*j/num-si*.1;dot(x,cx+r*Math.cos(a),cy+r*Math.sin(a),4.2,si===sh.length-1?'#fbbf24':'#38bdf8');}});text(x,names[z]+' (Z='+z+')',335,73,22,'#38bdf8',true);text(x,'শেল-বিন্যাস: '+sh.join(' · '),335,107,15,'#e2e8f0',true);text(x,'যোজ্যতা ইলেকট্রন = '+ve,335,139,16,'#fbbf24',true);text(x,'গ্রুপ '+g+' · পর্যায় '+sh.length,335,171,15,'#cbd5e1',true);text(x,tendency,335,204,14,'#34d399',true);text(x,'ইলেকট্রন বিন্যাস: '+full[z],18,260,16,'#cbd5e1',true);text(x,'প্রধান-গ্রুপ প্রবণতা; রাসায়নিক ধর্মে ব্যতিক্রম ও অক্সিডেশন অবস্থা থাকতে পারে।',18,294,11,'#94a3b8');});};

/* qc-17: compare isotope/isobar/isotone/isoelectronic correctly; isoelectronic uses charge. */
S.isotone=function(root,done){var cv=canvas(root,680,340),x=cv.x,mode='isotope';var ctl=controls(root,[{label:'A: প্রোটন Z₁',min:1,max:20,value:6},{label:'A: নিউট্রন N₁',min:0,max:25,value:6},{label:'A: আধান q₁',min:-3,max:3,value:0},{label:'B: প্রোটন Z₂',min:1,max:20,value:6},{label:'B: নিউট্রন N₂',min:0,max:25,value:8},{label:'B: আধান q₂',min:-3,max:3,value:0}],done);buttons(root,[{label:'আইসোটোপ',primary:true,click:function(){mode='isotope';done&&done();}},{label:'আইসোবার',click:function(){mode='isobar';done&&done();}},{label:'আইসোটোন',click:function(){mode='isotone';done&&done();}},{label:'আইসোইলেকট্রনিক',click:function(){mode='isoelectronic';done&&done();}}]);
 frame(root,function(){var v=ctl.read(),z1=v[0],n1=v[1],q1=v[2],z2=v[3],n2=v[4],q2=v[5],a1=z1+n1,a2=z2+n2,e1=z1-q1,e2=z2-q2,equal=mode==='isotope'?z1===z2&&n1!==n2:mode==='isobar'?a1===a2&&z1!==z2:mode==='isotone'?n1===n2&&z1!==z2:e1===e2&&z1!==z2;bg(x,cv.w,cv.h);text(x,'নিউক্লিয়াস ও প্রজাতির তুলনা',18,24,18,'#e2e8f0',true);
 function nuc(cx,z,n){for(var i=0;i<z+n&&i<45;i++){var a=i*2.39996,r=7+Math.sqrt(i+1)*4.7;dot(x,cx+Math.cos(a)*r,135+Math.sin(a)*r*.8,4.5,i<z?'#fb7185':'#38bdf8');}}
 nuc(160,z1,n1);nuc(510,z2,n2);text(x,'A: Z='+z1+' N='+n1+' A='+a1+' q='+q1+' e⁻='+e1,35,210,13,'#cbd5e1',true);text(x,'B: Z='+z2+' N='+n2+' A='+a2+' q='+q2+' e⁻='+e2,360,210,13,'#cbd5e1',true);text(x,({isotope:'আইসোটোপ: Z সমান, N আলাদা',isobar:'আইসোবার: A সমান, Z আলাদা',isotone:'আইসোটোন: N সমান, Z আলাদা',isoelectronic:'আইসোইলেকট্রনিক: ইলেকট্রন সংখ্যা সমান'}[mode]),18,253,14,'#38bdf8',true);text(x,equal?'✓ নির্বাচিত সম্পর্কটি মিলে গেছে':'শর্ত মিলছে না—স্লাইডার/আধান বদলান।',18,282,15,equal?'#34d399':'#f87171',true);text(x,'q = প্রোটন সংখ্যা − ইলেকট্রন সংখ্যা; নীল কণা নিউট্রন, লাল কণা প্রোটন।',18,315,11,'#94a3b8');});};

/* qc-26: teach 2n² as capacity of a chosen shell, not as actual subshell filling order. */
S.shellCapacity=function(root,done){var cv=canvas(root,680,320),x=cv.x;var ctl=controls(root,[{label:'নির্বাচিত প্রধান শক্তিস্তর n',min:1,max:7,value:3},{label:'এই শেলে ইলেকট্রন',min:0,max:98,value:8}],done);frame(root,function(){var ins=ctl.wrap.querySelectorAll('input'),n=+ins[0].value,cap=2*n*n;ins[1].max=String(cap);if(+ins[1].value>cap)ins[1].value=String(cap);var requested=ctl.read()[1],occ=Math.min(requested,cap);bg(x,cv.w,cv.h);text(x,'শেলের ধারণক্ষমতা · 2n² সূত্র',18,24,18,'#e2e8f0',true);var cx=190,cy=155;for(var sh=1;sh<=7;sh++){var r=14+sh*19;x.beginPath();x.arc(cx,cy,r,0,TAU);x.strokeStyle=sh===n?'#fbbf24':'#354d61';x.lineWidth=sh===n?3:1;x.stroke();if(sh===n)text(x,'n='+n,cx+r+5,cy-7,12,'#fbbf24',true);}var rSel=14+n*19;for(var j=0;j<occ;j++){var a=TAU*j/Math.max(1,cap)-Math.PI/2;dot(x,cx+rSel*Math.cos(a),cy+rSel*Math.sin(a),cap>40?2.2:3.7,'#38bdf8');}text(x,'নির্বাচিত শেল n = '+n,370,83,17,'#38bdf8',true);text(x,'সর্বোচ্চ ধারণক্ষমতা 2n² = '+cap,370,117,16,'#fbbf24',true);text(x,'বর্তমান occupancy = '+occ+' / '+cap,370,150,15,'#34d399',true);text(x,'সব ৭ শেলের তাত্ত্বিক মোট ধারণক্ষমতা = 2Σn² = 280',370,184,12,'#cbd5e1');text(x,'সতর্কতা: এটি shell capacity বোঝায়; বাস্তব electron filling order আলাদা উপস্তরের শক্তি অনুসরণ করে।',18,282,12,'#94a3b8');});};

