/* qc-31: representative period-3 atoms; after cation formation the empty outer shell disappears. */
S.valenceShell=function(root,done){var cv=canvas(root,680,330),x=cv.x;var ctl=controls(root,[{label:'বহিঃস্তরের ইলেকট্রন (প্রতিনিধি মৌল Na→Ar)',min:1,max:8,value:7}],done);var names=['','Na','Mg','Al','Si','P','S','Cl','Ar'];frame(root,function(){var e=ctl.read()[0],initial=[2,8,e],after,charge=0,msg;if(e<=3){after=[2,8];charge=e;msg='ধনায়ন গঠন: '+e+'টি ইলেকট্রন হারিয়ে [Ne]-এর মতো শেল-বিন্যাস';}else if(e>=5&&e<=7){after=[2,8,8];charge=-(8-e);msg='ঋণায়ন গঠন: '+(8-e)+'টি ইলেকট্রন নিয়ে বহিঃস্ত শেল পূর্ণ';}else if(e===4){after=initial.slice();msg='Si-এর মতো: একক ইলেকট্রন স্থানান্তরের বদলে সমযোজী বন্ধন সাধারণ';}else{after=initial.slice();msg='Ar-এর মতো পূর্ণ বহিঃস্ত শেল; সাধারণত সহজে আয়ন হয় না';}bg(x,cv.w,cv.h);text(x,'যোজ্যতা ইলেকট্রন → আয়ন/বন্ধন গঠন',18,24,18,'#e2e8f0',true);function atom(cx,vals,highlight){var cy=150;dot(x,cx,cy,15,'#fb7185');text(x,'+',cx,cy+4,11,'#071421',true,'center');for(var sh=0;sh<vals.length;sh++){var r=31+sh*27;x.beginPath();x.arc(cx,cy,r,0,TAU);x.strokeStyle=highlight&&sh===vals.length-1?'#fbbf24':'#486075';x.lineWidth=highlight&&sh===vals.length-1?2.5:1.2;x.stroke();for(var j=0;j<vals[sh];j++){var a=TAU*j/Math.max(1,vals[sh])-Math.PI/2;dot(x,cx+r*Math.cos(a),cy+r*Math.sin(a),4.2,highlight&&sh===vals.length-1?'#fbbf24':'#38bdf8');}}}atom(150,initial,true);atom(500,after,true);text(x,names[e]+' · আগে',105,255,14,'#cbd5e1',true);text(x,charge>0?names[e]+'³⁺'.replace('³',charge===3?'³':charge===2?'²':'¹'):charge<0?names[e]+(Math.abs(charge)===1?'⁻':Math.abs(charge)===2?'²⁻':'³⁻'):names[e],435,255,14,'#cbd5e1',true);text(x,msg,18,292,13,'#34d399',true);text(x,'প্রতিনিধি প্রধান-গ্রুপ মডেল; বাস্তব আয়ন গঠনের শক্তি/সম্ভাব্যতা আলাদাভাবে বিবেচ্য।',18,319,11,'#94a3b8');});};

/* qc-21: constrain the electron-count slider to the currently selected p or d subshell. */
S.spinOrbitalDiagram=function(root,done){var cv=canvas(root,680,310),x=cv.x;var ctl=controls(root,[{label:'উপস্তর: p=3 অথবা d=5 অরবিটাল',min:3,max:5,step:2,value:3},{label:'ইলেকট্রন সংখ্যা',min:0,max:6,value:4}],done);frame(root,function(){var ins=ctl.wrap.querySelectorAll('input'),count=+ins[0].value;ins[1].max=String(count*2);if(+ins[1].value>count*2)ins[1].value=String(count*2);var e=ctl.read()[1];bg(x,cv.w,cv.h);text(x,(count===3?'p':'d')+' উপস্তরের ইলেকট্রন স্পিন ও অরবিটাল ডায়াগ্রাম',18,24,17,'#e2e8f0',true);var occ=auditedOrbitalOccupancy(e,count*2);for(var k=0;k<count;k++){var w=count===3?92:66,gap=count===3?42:20,left=(680-(count*w+(count-1)*gap))/2,px=left+k*(w+gap),y=83;x.strokeStyle='#38bdf8';x.lineWidth=2;x.strokeRect(px,y,w,83);if(occ[k]>=1)text(x,'↑',px+w*.24,y+49,29,'#38bdf8',true);if(occ[k]>=2)text(x,'↓',px+w*.58,y+49,29,'#fbbf24',true);text(x,'অরবিটাল '+(k+1),px+w/2,y+104,11,'#94a3b8',false,'center');}text(x,'ইলেকট্রন: '+e+' / '+count*2,18,226,16,'#fbbf24',true);text(x,'একই অরবিটালে সর্বোচ্চ ২টি বিপরীত-স্পিন ইলেকট্রন (Pauli)।',18,253,13,'#cbd5e1');text(x,'সমশক্তির অরবিটালে আগে একক সমান্তরাল স্পিন (Hund)।',18,279,13,'#cbd5e1');});};

