/* Correct charge superscripts for the representative period-3 valence-shell ion model. */
var prevValenceShell=S.valenceShell;
S.valenceShell=function(root,done){var cv=canvas(root,680,330),x=cv.x;var ctl=controls(root,[{label:'বহিঃস্তরের ইলেকট্রন (Na → Ar)',min:1,max:8,value:7}],done);var names=['','Na','Mg','Al','Si','P','S','Cl','Ar'],supers=['','¹','²','³','⁴','⁵','⁶','⁷','⁸'];frame(root,function(){var e=ctl.read()[0],initial=[2,8,e],after,charge=0,msg;if(e<=3){after=[2,8];charge=e;msg='ধনায়ন গঠন: '+e+'টি ইলেকট্রন হারিয়ে [Ne]-এর মতো শেল-বিন্যাস';}else if(e>=5&&e<=7){after=[2,8,8];charge=-(8-e);msg='ঋণায়ন গঠন: '+(8-e)+'টি ইলেকট্রন নিয়ে বহিঃস্ত শেল পূর্ণ';}else if(e===4){after=initial.slice();msg='Si-এর মতো: ইলেকট্রন ভাগাভাগি/সমযোজী বন্ধন সাধারণ';}else{after=initial.slice();msg='Ar-এর মতো পূর্ণ বহিঃস্ত শেল; সাধারণত সহজে আয়ন হয় না';}bg(x,cv.w,cv.h);text(x,'যোজ্যতা ইলেকট্রন → আয়ন/বন্ধন গঠন',18,24,18,'#e2e8f0',true);function atom(cx,vals){var cy=150;dot(x,cx,cy,15,'#fb7185');text(x,'+',cx,cy+4,11,'#071421',true,'center');for(var sh=0;sh<vals.length;sh++){var r=31+sh*27;x.beginPath();x.arc(cx,cy,r,0,TAU);x.strokeStyle=sh===vals.length-1?'#fbbf24':'#486075';x.lineWidth=sh===vals.length-1?2.5:1.2;x.stroke();for(var j=0;j<vals[sh];j++){var a=TAU*j/Math.max(1,vals[sh])-Math.PI/2;dot(x,cx+r*Math.cos(a),cy+r*Math.sin(a),4.2,sh===vals.length-1?'#fbbf24':'#38bdf8');}}}atom(150,initial);atom(500,after);text(x,names[e]+' · আগে',105,255,14,'#cbd5e1',true);var ionName=names[e]+(charge>0?supers[charge]+'⁺':charge<0?supers[-charge]+'⁻':'');text(x,ionName+' · পরে',435,255,14,'#cbd5e1',true);text(x,msg,18,292,13,'#34d399',true);text(x,'সরল প্রধান-গ্রুপ মডেল; H-এর duet rule ও বাস্তব যৌগের ব্যতিক্রম আছে।',18,319,11,'#94a3b8');});};


