S.ionization=function(root,done){var cv=canvas(root,680,320),x=cv.x,mode='remove';var ctl=controls(root,[{label:'কার্যকর নিউক্লীয় আকর্ষণ (আপেক্ষিক)',min:1,max:10,value:6},{label:'পরমাণুর ব্যাসার্ধ (আপেক্ষিক)',min:1,max:10,value:4}],done);buttons(root,[{label:'ইলেকট্রন অপসারণ',primary:true,click:function(){mode='remove';done&&done();}},{label:'ইলেকট্রন গ্রহণ',click:function(){mode='add';done&&done();}}]);frame(root,function(){var v=ctl.read(),z=v[0],r=v[1],score=z/r,cx=200,cy=160,arrow=Math.max(26,Math.min(120,score*18));bg(x,cv.w,cv.h);text(x,'আয়নীকরণ শক্তি ও ইলেকট্রন গ্রহণ',18,24,17,'#e2e8f0',true);dot(x,cx,cy,24,'#fb7185');text(x,'+',cx,cy+5,18,'#071421',true,'center');x.beginPath();x.arc(cx,cy,Math.max(38,Math.min(110,r*9)),0,TAU);x.strokeStyle='#38bdf8';x.lineWidth=2;x.stroke();dot(x,cx+Math.max(38,Math.min(110,r*9)),cy,5,'#fbbf24');if(mode==='remove'){line(x,cx+Math.max(38,Math.min(110,r*9))+8,cy,cx+Math.max(38,Math.min(110,r*9))+8+arrow,cy,'#fbbf24',3);text(x,'e⁻ অপসারণ',350,84,15,'#fbbf24',true);text(x,'Z/r-এর গুণগত সূচক = '+score.toFixed(2),350,120,17,'#38bdf8',true);text(x,score>1.5?'এই সরল মডেলে আকর্ষণ তুলনামূলক বেশি':'এই সরল মডেলে আকর্ষণ তুলনামূলক কম',350,151,13);}else{line(x,350,cy,cx+Math.max(38,Math.min(110,r*9))+5,cy,'#34d399',3);dot(x,350,cy,6,'#34d399');text(x,'আসন্ন e⁻',350,cy-14,13,'#34d399',true);text(x,'Z/r = '+score.toFixed(2)+' (শুধু আকর্ষণের সরল সূচক)',350,100,14,'#38bdf8',true);text(x,'ইলেকট্রন-গ্রহণ এনথালপি শুধু Z/r দিয়ে নির্ধারিত হয় না।',350,132,12);text(x,'ইলেকট্রন বিন্যাস, উপস্তর ও ইলেকট্রন-বিকর্ষণও গুরুত্বপূর্ণ।',350,155,12);}text(x,'ব্যাসার্ধ ও আকর্ষণের প্রভাব ধারণামূলকভাবে দেখানো; এটি পরীক্ষাগারে মাপা IE/EA নয়।',18,285,12,'#94a3b8');});};

/* qc-23: make the probability cloud stable (no orbit-like particle motion); show p-lobe density. */
S.electroncloud=function(root,done){var cv=canvas(root,680,320),x=cv.x;var ctl=controls(root,[{label:'অরবিটাল: 0 = s, 1 = pₓ',min:0,max:1,value:0},{label:'মেঘের বিস্তার',min:30,max:100,value:65}],done);frame(root,function(){var v=ctl.read(),p=v[0]===1,spread=v[1],cx=250,cy=155;bg(x,cv.w,cv.h);text(x,'আধুনিক পরমাণু মডেল: সম্ভাব্যতার মেঘ',18,24,17,'#e2e8f0',true);dot(x,cx,cy,10,'#fb7185');for(var i=0;i<1800;i++){var u=((i*.61803398875)%1),a=i*2.3999632297,r=spread*Math.sqrt(u),angular=Math.cos(a)*Math.cos(a);if(p&&(((i*0.754877666)%1)>angular))continue;var xx=cx+r*Math.cos(a),yy=cy+r*Math.sin(a)*.78;if(p)yy=cy+r*Math.sin(a)*.68;var alpha=Math.max(.04,.36*(1-r/(spread*1.05)));x.fillStyle='rgba(56,189,248,'+alpha+')';x.beginPath();x.arc(xx,yy,1.5,0,TAU);x.fill();}if(p){line(x,cx,cy-105,cx,cy+105,'#fbbf24',1.5,[4,4]);text(x,'নোডাল সমতল',cx+8,cy+115,11,'#fbbf24');}text(x,p?'pₓ: নোডাল সমতলের দুই পাশে লোব':'s: আনুমানিক গোলীয় মেঘ',405,100,14,'#38bdf8',true);text(x,'বিন্দুর ঘনত্ব সম্ভাবনার ধারণা দেখায়; বিন্দু ইলেকট্রনের চলার পথ নয়।',405,132,12);text(x,'স্কিম্যাটিক 2D উপস্থাপনা; পূর্ণ 3D wavefunction নয়।',18,295,12,'#94a3b8');});};

/* qc-24: conventional nuclide symbol uses actual Unicode subscripts, not parentheses. */
S.atomicNotation2=function(root,done){var cv=canvas(root,680,310),x=cv.x;var syms=['','H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca','Sc','Ti','V','Cr','Mn','Fe','Co','Ni','Cu','Zn'];var supers='⁰¹²³⁴⁵⁶⁷⁸⁹',subs='₀₁₂₃₄₅₆₇₈₉';function trans(n,map){return String(n).split('').map(function(c){return map[+c]||c;}).join('');}function sup(n){return trans(n,supers);}function sub(n){return trans(n,subs);}var ctl=controls(root,[{label:'পারমাণবিক সংখ্যা Z',min:1,max:30,value:11},{label:'ভরসংখ্যা A',min:1,max:70,value:23},{label:'আধান q (+ ধনায়ন, − ঋণায়ন)',min:-3,max:3,value:1}],done);frame(root,function(){var v=ctl.read(),z=v[0],A=v[1],q=v[2],n=A-z,e=z-q,ok=A>=z&&e>=0;bg(x,cv.w,cv.h);text(x,'নিউক্লাইড/আয়ন প্রতীক নির্মাতা',18,24,18,'#e2e8f0',true);if(!ok){text(x,'অবৈধ: A ≥ Z এবং ইলেকট্রন সংখ্যা ঋণাত্মক নয়।',20,63,14,'#f87171',true);}else{var sym=syms[z],charge=q===0?'':Math.abs(q)===1?(q>0?'⁺':'⁻'):sup(Math.abs(q))+(q>0?'⁺':'⁻');text(x,sup(A),88,120,20,'#38bdf8',true,'center');text(x,sub(z),88,149,20,'#38bdf8',true,'center');text(x,sym,123,144,42,'#e2e8f0',true);if(q!==0)text(x,charge,176,111,18,'#fbbf24',true);text(x,'প্রতীক: '+sup(A)+sub(z)+sym+charge,30,194,20,'#e2e8f0',true);}text(x,'মৌল: '+syms[z],300,85,17,'#fbbf24',true);text(x,'প্রোটন Z = '+z,300,120,15,'#fb7185');text(x,'নিউট্রন N = A − Z = '+(ok?n:'—'),300,153,15,'#38bdf8');text(x,'ইলেকট্রন = Z − q = '+(ok?e:'—'),300,186,15,'#fbbf24');text(x,'Z মৌল নির্ধারণ করে; A = প্রোটন + নিউট্রন।',18,275,12,'#94a3b8');});};

/* qc-25: compare isotopes, isobars and isotones; each button loads a canonical valid example. */
S.isotopeCompare=function(root,done){var cv=canvas(root,680,320),x=cv.x,mode='isotope';var ctl=controls(root,[{label:'A: Z (প্রোটন)',min:1,max:20,value:6},{label:'A: N (নিউট্রন)',min:0,max:25,value:6},{label:'B: Z (প্রোটন)',min:1,max:20,value:6},{label:'B: N (নিউট্রন)',min:0,max:25,value:8}],done);function set(v){var ins=ctl.wrap.querySelectorAll('input');v.forEach(function(n,i){ins[i].value=String(n);ins[i].dispatchEvent(new Event('input',{bubbles:true}));});}buttons(root,[{label:'আইসোটোপ',primary:true,click:function(){mode='isotope';set([6,6,6,8]);done&&done();}},{label:'আইসোবার',click:function(){mode='isobar';set([6,6,8,4]);done&&done();}},{label:'আইসোটোন',click:function(){mode='isotone';set([6,6,8,6]);done&&done();}}]);frame(root,function(){var v=ctl.read(),z1=v[0],n1=v[1],z2=v[2],n2=v[3],a1=z1+n1,a2=z2+n2,valid=true,equal=mode==='isotope'?z1===z2&&n1!==n2:mode==='isobar'?a1===a2&&z1!==z2:n1===n2&&z1!==z2;bg(x,cv.w,cv.h);text(x,'আইসোটোপ, আইসোবার ও আইসোটোন তুলনা',18,24,18,'#e2e8f0',true);function nuc(cx,z,n){for(var i=0;i<Math.min(z+n,45);i++){var a=i*2.39996,r=8+Math.sqrt(i+1)*4.7;dot(x,cx+Math.cos(a)*r,128+Math.sin(a)*r*.75,4.5,i<z?'#fb7185':'#38bdf8');}}nuc(160,z1,n1);nuc(510,z2,n2);text(x,'A: Z='+z1+'  N='+n1+'  A='+a1,42,210,14,'#cbd5e1',true);text(x,'B: Z='+z2+'  N='+n2+'  A='+a2,390,210,14,'#cbd5e1',true);text(x,({isotope:'আইসোটোপ: একই Z, ভিন্ন N',isobar:'আইসোবার: একই A, ভিন্ন Z',isotone:'আইসোটোন: একই N, ভিন্ন Z'}[mode]),18,250,15,'#38bdf8',true);text(x,equal?'✓ এই জুটিতে নির্বাচিত সম্পর্কটি সত্য।':'স্লাইডার বদলে নির্বাচিত সম্পর্কের শর্ত পূরণ করুন।',18,280,14,equal?'#34d399':'#f87171',true);text(x,'লাল কণা প্রোটন; নীল কণা নিউট্রন। A = Z + N।',18,308,11,'#94a3b8');});};

/* qc-28: expose the full conventional filling sequence through Ba (Z=56), including 6s. */
