/* qc-07: wavelength display must follow the selected transition, not always show Balmer lines. */
S.spectrum=function(root,done){var cv=canvas(root,680,330),x=cv.x;var ctl=controls(root,[{label:'শুরুর স্তর nᵢ',min:2,max:7,value:4},{label:'শেষ স্তর n_f',min:1,max:6,value:2}],done);frame(root,function(){var inputs=ctl.wrap.querySelectorAll('input'),ni=+inputs[0].value;inputs[1].max=String(ni-1);if(+inputs[1].value>=ni)inputs[1].value=String(ni-1);var v=ctl.read();ni=v[0];var nf=v[1],de=13.6*(1/(nf*nf)-1/(ni*ni)),lam=1239.841984/de,series=nf===1?'Lyman · অতিবেগুনি':nf===2?'Balmer · দৃশ্যমান থেকে নিকট UV':nf===3?'Paschen · অবলোহিত':nf===4?'Brackett · অবলোহিত':nf===5?'Pfund · অবলোহিত':'Humphreys · অবলোহিত',color=lam<380?'#a78bfa':lam<=450?'#6366f1':lam<=495?'#38bdf8':lam<=570?'#34d399':lam<=590?'#facc15':lam<=620?'#fb923c':lam<=700?'#fb7185':'#a3a3a3';bg(x,cv.w,cv.h);text(x,'হাইড্রোজেনের রেখা-বর্ণালি: নির্বাচিত transition',18,24,18,'#e2e8f0',true);for(var n=1;n<=7;n++){var y=245-n*27;line(x,35,y,310,y,n===ni?'#fbbf24':n===nf?'#fb7185':'#496176',n===ni||n===nf?3:1.3);text(x,'n='+n,5,y+4,11,'#cbd5e1');}line(x,255,245-ni*27,255,245-nf*27,'#fb7185',3);text(x,'ΔE = '+de.toFixed(4)+' eV',350,66,17,'#fbbf24',true);text(x,'λ = hc/ΔE ≈ '+lam.toFixed(1)+' nm',350,98,15,'#38bdf8',true);text(x,series,350,125,14,'#cbd5e1',true);text(x,'নির্গত ফোটনের শক্তি = শক্তিস্তরের পার্থক্য',350,151,12);var left=42,right=635,axisY=226,minL=90,maxL=13000,logMin=Math.log10(minL),logMax=Math.log10(maxL);function pxFor(w){return left+(Math.log10(w)-logMin)/(logMax-logMin)*(right-left);}line(x,left,axisY,right,axisY,'#718096',2);[100,400,700,1000,10000].forEach(function(w){var px=pxFor(w);line(x,px,axisY-6,px,axisY+7,'#718096',1);text(x,String(w),px,axisY+23,10,'#cbd5e1',false,'center');});if(lam>=minL&&lam<=maxL){var mx=pxFor(lam);line(x,mx,axisY-32,mx,axisY-2,color,4);text(x,'নির্বাচিত '+lam.toFixed(0)+' nm',Math.max(100,Math.min(565,mx)),axisY-41,11,color,true,'center');}text(x,'তরঙ্গদৈর্ঘ্য (nm) · logarithmic scale',left,288,12,'#cbd5e1',true);text(x,'Balmer reference lines শুধু n_f = 2 হলে:',18,309,10,'#94a3b8');if(nf===2){text(x,'410.2 · 434.0 · 486.1 · 656.3 nm',215,309,10,'#94a3b8');}else{text(x,'বর্তমান transition অন্য series-এ; Balmer রেখা এখানে reference হিসেবে দেখানো হয়নি।',215,309,10,'#94a3b8');}});};

/* qc-31: conventional ion symbols omit a superscript 1 and show honest shell counts. */
S.valenceShell=function(root,done){var cv=canvas(root,680,330),x=cv.x;var ctl=controls(root,[{label:'বহিঃস্তরের ইলেকট্রন (প্রতিনিধি Na → Ar)',min:1,max:8,value:7}],done);var names=['','Na','Mg','Al','Si','P','S','Cl','Ar'],supers=['','¹','²','³','⁴','⁵','⁶','⁷','⁸'];frame(root,function(){var e=ctl.read()[0],initial=[2,8,e],after,charge=0,msg;if(e<=3){after=[2,8];charge=e;msg='ধনায়ন: '+e+'টি বহিঃস্ত ইলেকট্রন ত্যাগ করে [Ne]-সদৃশ বিন্যাস';}else if(e>=5&&e<=7){after=[2,8,8];charge=-(8-e);msg='ঋণায়ন: '+(8-e)+'টি ইলেকট্রন গ্রহণ করে [Ar]-সদৃশ বিন্যাস';}else if(e===4){after=initial.slice();msg='Si-ধরনের উদাহরণ: ইলেকট্রন ভাগাভাগি / সমযোজী বন্ধন';}else{after=initial.slice();msg='Ar: পূর্ণ বহিঃস্ত শেল; সাধারণত সহজে আয়ন হয় না';}bg(x,cv.w,cv.h);text(x,'যোজ্যতা ইলেকট্রন → আয়ন গঠন',18,24,18,'#e2e8f0',true);function atom(cx,vals){var cy=150;dot(x,cx,cy,15,'#fb7185');text(x,'+',cx,cy+4,11,'#071421',true,'center');for(var sh=0;sh<vals.length;sh++){var r=31+sh*27;x.beginPath();x.arc(cx,cy,r,0,TAU);x.strokeStyle=sh===vals.length-1?'#fbbf24':'#486075';x.lineWidth=sh===vals.length-1?2.5:1.2;x.stroke();for(var j=0;j<vals[sh];j++){var a=TAU*j/Math.max(1,vals[sh])-Math.PI/2;dot(x,cx+r*Math.cos(a),cy+r*Math.sin(a),4.2,sh===vals.length-1?'#fbbf24':'#38bdf8');}}}atom(150,initial);atom(500,after);text(x,names[e]+' · আগে',105,255,14,'#cbd5e1',true);var ionName=names[e]+(charge>0?(charge===1?'':supers[charge])+'⁺':charge<0?(charge===-1?'':supers[-charge])+'⁻':'');text(x,ionName+' · পরে',435,255,14,'#cbd5e1',true);text(x,msg,18,292,13,'#34d399',true);text(x,'সরল প্রধান-গ্রুপ মডেল; H-এর duet rule, covalent compounds ও বাস্তব ব্যতিক্রম বিবেচ্য।',18,319,11,'#94a3b8');});};



/* qc-23 final: use independent precomputed samples; avoid correlated spiral/trajectory artifacts. */
S.electroncloud=function(root,done){var cv=canvas(root,680,320),x=cv.x;var ctl=controls(root,[{label:'অরবিটাল: 0 = s, 1 = pₓ',min:0,max:1,value:0},{label:'মেঘের বিস্তার',min:30,max:100,value:65}],done);var samples=[];for(var i=0;i<2400;i++){var a=Math.random()*TAU,u=Math.max(.0001,Math.random()),r=Math.min(1.3,Math.sqrt(-Math.log(1-u))*.48);samples.push({a:a,r:r,keep:Math.random()});}frame(root,function(){var v=ctl.read(),p=v[0]===1,spread=v[1],cx=250,cy=155;bg(x,cv.w,cv.h);text(x,'আধুনিক পরমাণু মডেল: সম্ভাব্যতার মেঘ',18,24,17,'#e2e8f0',true);for(var i=0;i<samples.length;i++){var s=samples[i],angular=Math.cos(s.a)*Math.cos(s.a);if(p&&s.keep>angular)continue;var r=s.r*spread,xx=cx+r*Math.cos(s.a),yy=cy+r*Math.sin(s.a)*.7,alpha=Math.max(.06,.46*(1-s.r/1.45));x.fillStyle='rgba(56,189,248,'+alpha+')';x.beginPath();x.arc(xx,yy,1.45,0,TAU);x.fill();}dot(x,cx,cy,9,'#fb7185');if(p){line(x,cx,cy-105,cx,cy+105,'#fbbf24',1.5,[4,4]);text(x,'নোডাল সমতল',cx+8,cy+115,11,'#fbbf24');}text(x,p?'pₓ: নোডাল সমতলের দুই পাশে দুই লোব':'s: কেন্দ্রের কাছে বেশি ঘন গোলীয় মেঘ',405,100,14,'#38bdf8',true);text(x,'বিন্দুর ঘনত্ব সম্ভাবনার ধারণা দেয়; ইলেকট্রন কোনো আঁকা পথে ঘোরে না।',405,132,12);text(x,'2D স্কিম্যাটিক—পূর্ণ 3D wavefunction বা পরিমাপ নয়।',18,295,12,'#94a3b8');});};



