 root.appendChild(cv.c);var read=document.createElement('div');read.className='reaction-energy-readouts';read.id='re-energy-result';root.appendChild(read);var caveat=document.createElement('p');caveat.className='fl-caveat';caveat.textContent='গ্রাফটি স্কিম্যাটিক; শক্তির মান একটি ধারণাগত উদাহরণ, নির্দিষ্ট কোনো বিক্রিয়ার পরীক্ষামূলক profile নয়।';root.appendChild(caveat);
